import { readFileSync } from 'node:fs'
import { createCanon } from '../src/lib/canon.js'
import { buildIndex } from '../src/lib/search.js'

// Generated by `npm run data`; `npm test` runs that first.
export const data = JSON.parse(readFileSync(new URL('../src/data/scriptures.json', import.meta.url), 'utf8'))
export const canon = createCanon(data)

let index
export const getIndex = () => (index ??= buildIndex(data.text))
